import itertools

def compute_cost(seq):
    n = len(seq)
    total = 0
    for k in range(1, n):
        Ck = 0
        for i in range(n - k):
            Ck += seq[i] * seq[i + k]
        total += Ck * Ck
    return total

# Fixed values: seq[0]=-1, seq[8]=1, seq[6]=-1
fixed = {0: -1, 8: 1, 6: -1}

# Generate all possibilities for the remaining 7 positions
remaining_indices = [i for i in range(10) if i not in fixed]
solutions = []
for bits in itertools.product([-1, 1], repeat=len(remaining_indices)):
    seq = [0] * 10
    for idx, val in fixed.items():
        seq[idx] = val
    for i, idx in enumerate(remaining_indices):
        seq[idx] = bits[i]

    cost = compute_cost(seq)
    if cost <= 20:
        solutions.append((seq, cost))

print(f"Found {len(solutions)} solutions")
for seq, cost in solutions[:20]:
    print(f"seq={seq}, cost={cost}")
